CREATE TABLE `employee_payroll_component_details` (
  `payroll_component_detail_id` bigint NOT NULL AUTO_INCREMENT,
  `payroll_detail_id` bigint NOT NULL,
  `component_id` bigint DEFAULT NULL,
  `component_code` varchar(30) NOT NULL,
  `component_name` varchar(100) NOT NULL,
  `component_type` enum('EARNING','DEDUCTION','EMPLOYER_CONTRIBUTION') NOT NULL,
  `calculation_scope` enum('COMPONENT','AGGREGATE') NOT NULL DEFAULT 'COMPONENT',
  `calculation_order` int DEFAULT NULL,
  `calculation_type` enum('FIXED','PERCENTAGE','FORMULA','MANUAL','STATUTORY') NOT NULL DEFAULT 'FIXED',
  `component_value` decimal(12,2) NOT NULL DEFAULT '0.00',
  `percentage_base` varchar(30) DEFAULT 'NONE',
  `percentage_value` decimal(12,2) NOT NULL DEFAULT '0.00',
  `formula_expression` text,
  `calculated_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `is_taxable` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`payroll_component_detail_id`),
  KEY `idx_epcd_detail` (`payroll_detail_id`),
  KEY `idx_epcd_detail_scope` (`payroll_detail_id`,`calculation_scope`)
) ENGINE=InnoDB AUTO_INCREMENT=30639 DEFAULT CHARSET=latin1;
