--
-- Table structure for table `employee_payslips`
--

DROP TABLE IF EXISTS `employee_payslips`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `employee_payslips` (
  `payslip_id` bigint NOT NULL AUTO_INCREMENT,
  `payroll_detail_id` bigint NOT NULL,
  `active_detail_id` bigint GENERATED ALWAYS AS (if((`payslip_status` <> _latin1'REVOKED'),`payroll_detail_id`,NULL)) STORED,
  `payslip_number` varchar(100) NOT NULL,
  `payslip_status` enum('PENDING','GENERATED','PUBLISHED','REVOKED') NOT NULL DEFAULT 'PENDING',
  `file_path` varchar(500) DEFAULT NULL,
  `generated_by` varchar(50) DEFAULT NULL,
  `generated_at` datetime DEFAULT NULL,
  `published_by` varchar(50) DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `revoked_by` varchar(50) DEFAULT NULL,
  `revoked_at` datetime DEFAULT NULL,
  `revocation_reason` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`payslip_id`),
  UNIQUE KEY `uq_eps_active_detail` (`active_detail_id`),
  KEY `idx_eps_detail` (`payroll_detail_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1003 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

