DROP TABLE IF EXISTS `payroll_cycle_status_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payroll_cycle_status_log` (
  `log_id` bigint NOT NULL AUTO_INCREMENT,
  `payroll_cycle_id` bigint NOT NULL,
  `cycle_code` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `payroll_detail_id` bigint DEFAULT NULL,
  `emp_id` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `action` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `from_status` varchar(30) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `to_status` varchar(30) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `remarks` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `performed_by` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `performed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`log_id`),
  KEY `idx_pcsl_cycle` (`payroll_cycle_id`,`log_id`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
